class Solution {
public:
    long long minimumCost(string s) {
        int n = s.size();
        long long ans = 0;
        for (int j = 0; j < n - 1; j++) {
            if (s[j] != s[j + 1]) {
                long long left = j + 1;
                long long right = (long long)(n - 1) - j;
                ans += (left < right) ? left : right;
            }
        }
        return ans;
    }
};
